<template><div class="toolbar"><a-select v-model:value="accountId" style="width:240px" :options="accountOptions" placeholder="选择账号"/><a-breadcrumb><a-breadcrumb-item><a @click="goRoot">根目录</a></a-breadcrumb-item><a-breadcrumb-item v-for="(item,index) in stack" :key="item.id"><a @click="go(index)">{{item.name}}</a></a-breadcrumb-item></a-breadcrumb><div class="grow"/><a-button type="primary" :disabled="!accountId" @click="folderVisible=true"><FolderAddOutlined/>新建文件夹</a-button></div><a-card class="panel-card"><a-table :loading="loading" :data-source="files" :columns="columns" row-key="id" @row="rowEvents"><template #bodyCell="{column,record}"><template v-if="column.key==='name'"><FolderFilled v-if="record.is_directory" style="color:#f0ad35"/> <FileOutlined v-else/> <strong>{{record.name}}</strong></template><template v-if="column.key==='size'">{{record.is_directory?'-':formatSize(record.size)}}</template><template v-if="column.key==='time'">{{formatTime(record.modified_time)}}</template></template></a-table></a-card><a-modal v-model:open="folderVisible" title="新建文件夹" @ok="createFolder"><a-input v-model:value="folderName" placeholder="文件夹名称"/></a-modal></template><script setup lang="ts">import{computed,onMounted,ref,watch}from'vue';import{message}from'ant-design-vue';import{FolderAddOutlined,FolderFilled,FileOutlined}from'@ant-design/icons-vue';import{get,post}from'../../services/http';import{formatSize,formatTime}from'../../core/format';import type{Account,FileItem}from'../../types';const accounts=ref<Account[]>([]),accountId=ref<number>(),files=ref<FileItem[]>([]),stack=ref<FileItem[]>([]),loading=ref(false),folderVisible=ref(false),folderName=ref('');const columns=[{title:'名称',key:'name'},{title:'类型',dataIndex:'is_directory',customRender:({text}:{text:boolean})=>text?'文件夹':'文件'},{title:'大小',key:'size'},{title:'修改时间',key:'time'}],accountOptions=computed(()=>accounts.value.map(a=>({value:a.id,label:`${a.name||a.username} · ${a.source_type}`})));async function load(){if(!accountId.value)return;loading.value=true;try{const parent=stack.value.at(-1);const data=await get<FileItem[]>(`/path/files?account_id=${accountId.value}&path=${encodeURIComponent(parent?.id||'')}&page=1&page_size=200`);files.value=Array.isArray(data)?data:[]}finally{loading.value=false}}const rowEvents=(r:FileItem)=>({onDblclick:()=>{if(r.is_directory){stack.value.push(r);load()}}});function goRoot(){stack.value=[];load()}function go(i:number){stack.value=stack.value.slice(0,i+1);load()}async function createFolder(){const account=accounts.value.find(a=>a.id===accountId.value);await post('/path/create',{parent_id:stack.value.at(-1)?.id||'',parent_path:stack.value.map(x=>x.name).join('/'),name:folderName.value,source_type:account?.source_type,account_id:accountId.value});folderVisible.value=false;folderName.value='';message.success('文件夹已创建');load()}watch(accountId,()=>{stack.value=[];load()});onMounted(async()=>{accounts.value=await get('/account/list');accountId.value=accounts.value[0]?.id})</script>
